"""Immersive room compositions. Story content stays in data.py."""
from html import escape as e
from pathlib import Path
import json
import data as d

def scene(name,kind=''):
    return f'<div class="environment {kind}" aria-hidden="true"><img src="assets/art/{name}.webp" alt="" fetchpriority="high"></div>'

def title(kicker,name,description=''):
    return f'<div class="scene-title"><span class="eyebrow">{kicker}</span><h1>{name}</h1><p>{description}</p></div>'

def hotspot(label,attrs,x,y,number):
    return f'<button class="hotspot" style="--x:{x}%;--y:{y}%" {attrs}><span class="hotspot-point">{number}</span><span class="hotspot-label">{label}<i>↗</i></span></button>'

def sheet(id,title,content,kicker='THE HOUSE / RECORDS'):
    return f'<dialog class="object-sheet" id="{id}"><form method="dialog"><button class="dialog-close" aria-label="닫기">×</button></form><span class="eyebrow">{kicker}</span><h2>{title}</h2>{content}</dialog>'

def entrance():
    return scene('alley','entry-environment')+f'''<section class="entry-copy"><span class="eyebrow">A HOUSE IN THE BACK ALLEY</span><div class="entry-ornament" aria-hidden="true">✧</div><p class="entry-location">자유교역도시 베일하운</p><h1>골목<br>시술소<span class="title-dot">.</span></h1><p class="entry-subtitle">{e(d.CONFIG['TITLE'])}</p><button id="enter" class="enter-button"><span>문을 열고 들어가기<small>만 19세 이상입니다</small></span><i aria-hidden="true">↗</i></button><p class="age-notice"><b>19+</b> 만 19세 미만은 입장할 수 없습니다</p></section><div class="entry-coordinate"><span>VEILHAUN</span><i></i><span>THE BACK ALLEY</span></div><div class="entry-bottom"><span>글 · 설정 {e(d.CONFIG['AUTHOR'])}</span><span>이어폰을 끼고 천천히 둘러보세요</span><span data-status>영업중</span></div>'''

def home():
    menu=''.join(f'<li><div><h3>{e(n)}</h3><p>{e(t)}</p></div><b>{e(p)}</b></li>' for n,p,t in d.MENUS)
    reservations=''.join(f'<li><time>{e(r.get("time",""))}</time><span>{e(r.get("name",""))}</span><span>{e(r.get("menu",""))}</span></li>' for r in d.CONFIG['RESERVATIONS']) or '<li class="empty-reservation">아직 적힌 예약이 없습니다</li>'
    reputation=''.join(f'<li class="{"current" if i==0 else ""}"><span>{i+1:02}</span>{e(x)}</li>' for i,x in enumerate(d.REPUTATION))
    rumors=''.join(f'<li class="pinned-note">{e(x)}</li>' for x in d.RUMORS[:4])
    return scene('reception')+title('01 / RECEPTION','잠시, 쉬어 가세요.','장부를 펼치거나, 칸막이 너머에 귀를 기울여 보세요.')+f'''<div class="room-status"><i></i><span data-status></span><span data-period></span></div><div class="scene-interactions" aria-label="접수대 둘러보기">{hotspot('오늘의 장부','data-open="ledger-sheet"',72,61,'01')}{hotspot('시술 메뉴','data-open="menu-sheet"',87,74,'02')}{hotspot('칸막이 너머','id="partition" aria-describedby="voice"',49,45,'03')}{hotspot('골목의 소문','data-open="rumors-sheet"',27,57,'04')}</div><div class="voice-caption"><span class="eyebrow">BEYOND THE CURTAIN</span><q id="voice" aria-live="polite">가만히 귀를 기울여 보세요</q></div><div class="scene-bottom"><p><span class="tiny-orbit"></span>빛나는 표식을 눌러 둘러보세요</p><a href="characters.html">대기실로 가기 <span>→</span></a></div>'''+sheet('ledger-sheet','오늘의 장부',f'<p class="sheet-date" data-date></p><p data-hours></p><ul class="reservation-list">{reservations}</ul><h3>골목의 평판</h3><ol class="reputation">{reputation}</ol>')+sheet('menu-sheet','손끝에 맡기는 시간',f'<ul class="treatment-menu">{menu}</ul><p class="handwriting">{e(d.COPY["menu_note"])}</p><small>{e(d.COPY["currency"])}</small>')+sheet('rumors-sheet','골목에서 들은 말',f'<ul class="rumor-wall">{rumors}</ul>','WHISPERS / VEILHAUN')

def characters():
    ch=d.CHARACTERS[0]
    people=''.join(f'<button class="person-row {"selected" if i==0 else ""}" data-person="{i}" data-group="{e(c["group"])}" aria-pressed="{str(i==0).lower()}"><img src="{c["thumbnail"]}" alt="" loading="lazy"><span class="person-index">0{i+1}</span><span><strong>{c["name"]}</strong><small>{c["race"]} · {c["group"]}</small></span><i>↗</i></button>' for i,c in enumerate(d.CHARACTERS))
    return f'''<div class="waiting-intro"><span class="eyebrow">02 / THE WAITING ROOM</span><h1>저마다의 사정,<br>저마다의 매듭.</h1><p>대기실에서 마주치는 다섯 사람</p></div><div class="waiting-layout"><section class="guest-list"><div class="tabs" aria-label="인물 분류"><button class="tab active" data-filter="전체" aria-pressed="true">모두</button><button class="tab" data-filter="직원" aria-pressed="false">직원</button><button class="tab" data-filter="손님" aria-pressed="false">손님</button></div>{people}</section><section class="character-stage" id="selected-person" style="--person:{ch['color']}"><div class="portrait" data-portrait><div class="portrait-placeholder" hidden><span>A</span><p>그림을 기다리는 자리</p></div><img src="{ch['portrait']}" alt="{ch['name']}" fetchpriority="high"></div><div class="character-caption"><span class="eyebrow" id="person-meta">{ch['race']} · {ch['age']} · {ch['role']}</span><h2 id="person-name">{ch['name']}</h2><blockquote id="person-hook">“{e(ch['hook'])}”</blockquote><a class="text-link" id="chart-link" href="char/{ch['slug']}.html">카르테 열기 <span>↗</span></a></div><div class="portrait-counter"><span id="person-count">01</span> / 05</div><div class="person-arrows"><button data-person-step="-1" aria-label="이전 인물">←</button><button data-person-step="1" aria-label="다음 인물">→</button></div></section></div>'''

def rules():
    depths=''.join(f'<li><b>{i:02}</b><div><h3>{e(n)}</h3><p>{e(t)}</p></div></li>' for i,(n,t) in enumerate(d.DEPTHS,1))
    heat=''.join(f'<button class="heat-step {"active" if i==0 else ""}" data-heat="{i}" aria-pressed="{str(i==0).lower()}"><i aria-hidden="true"></i><span>{e(x)}</span></button>' for i,x in enumerate(d.HEAT))
    book=f'''<nav class="book-tabs" aria-label="노트 페이지"><button data-book="0" aria-pressed="true">I. 결</button><button data-book="1" aria-pressed="false">II. 달아오름</button><button data-book="2" aria-pressed="false">III. 관계</button></nav><section data-book-page="0"><h3>{e(d.COPY['knots_title'])}</h3><p>{e(d.COPY['knots_definition'])}</p><p class="ink-note">{e(d.COPY['knots_progress'])}</p><ol class="depth-list">{depths}</ol></section><section data-book-page="1" hidden><h3>달아오름</h3><div class="heat-scale">{heat}</div><div class="heat-meter"><i></i></div><p class="heat-label">{e(d.HEAT[0])}</p></section><section data-book-page="2" hidden><h3>허용선</h3><ol class="numbered-steps">{''.join('<li>'+e(x)+'</li>' for x in d.BOUNDARIES)}</ol><h3>관계</h3><p class="relation-stages">{' → '.join(d.RELATION_STAGES)}</p><p>{e(d.COPY['currency'])}</p></section><div class="book-footer"><button data-book-step="-1" aria-label="노트 이전 장">←</button><span id="book-count">01 / 03</span><button data-book-step="1" aria-label="노트 다음 장">→</button></div>'''
    return scene('perfumery')+title('03 / THE STILL ROOM','향을 고르는 시간.','작은 병 하나에도, 풀어낼 매듭이 있습니다.')+f'''<div class="oil-interactions"><button data-oil="calm" class="oil-select" style="--x:51%;--y:66%" aria-pressed="false"><span class="oil-orbit"></span><span>진정<small>CALM</small></span></button><button data-oil="warm" class="oil-select" style="--x:62%;--y:65%" aria-pressed="false"><span class="oil-orbit"></span><span>온열<small>WARMTH</small></span></button><button data-oil="unknown" class="oil-select" style="--x:58%;--y:81%" aria-label="라벨이 찢긴 빈 병" aria-pressed="false"><span class="oil-orbit"></span><span>?<small>UNKNOWN</small></span></button></div><div class="oil-result"><span class="eyebrow">ESSENCE / SELECT A BOTTLE</span><p id="oil-note" aria-live="polite">향유병을 골라 보세요.</p><div class="scent-lines" aria-hidden="true"><i></i><i></i><i></i></div></div><button class="notebook-trigger" data-open="notebook-sheet"><span class="book-icon" aria-hidden="true">▤</span><span>레이나의 조향 노트<small>매듭과 달아오름에 관하여</small></span><i>↗</i></button>'''+sheet('notebook-sheet','레이나의 조향 노트',book,'REINA’S FIELD NOTES')

def city():
    places=''.join(f'<button class="place-row {"active" if i==0 else ""}" data-place="{i}" aria-pressed="{str(i==0).lower()}"><span>0{i+1}</span><strong>{e(p["name"])}</strong><i>↗</i></button>' for i,p in enumerate(d.PLACES))
    pins=''.join(f'<button class="map-pin" data-place="{i}" style="--x:{x}%;--y:{y}%" aria-label="{e(p["name"])}" aria-pressed="{str(i==0).lower()}"><i></i><span>{e(p["name"])}</span></button>' for i,(p,(x,y)) in enumerate(zip(d.PLACES,[(15,27),(48,40),(72,17),(82,68),(24,72),(51,85)])))
    return title('05 / VEILHAUN','도시의 맥박을 따라.','심연구 입구 위에 선 자유교역도시')+f'''<div class="city-layout"><nav class="places" aria-label="도시 장소">{places}<p class="key-hint">↑ ↓ 장소 이동</p></nav><section class="city-stage"><div class="city-cartography"><svg viewBox="0 0 900 460" preserveAspectRatio="none" aria-hidden="true"><path class="river" d="M-20 50Q260 100 290 250T940 390"/><path d="M50 100L220 90 350 210 590 80 780 90M80 340L280 260 440 250 670 330 840 280M220 90L190 160 280 260 240 380M590 80L570 200 670 330M350 210L440 250 570 200"/><circle cx="440" cy="250" r="130"/><circle cx="440" cy="250" r="145"/></svg><span class="map-watermark">VEILHAUN</span><span class="compass" aria-hidden="true">N<br>✧</span>{pins}<span class="map-caption">장소를 탐색하는 개념도</span></div><div class="city-window"><img data-scene src="images/B/{d.PLACES[0]['code']}.webp" alt="{e(d.PLACES[0]['name'])}"><article class="city-info"><span class="eyebrow" id="place-number">01 / VEILHAUN</span><h2 id="place-name">{e(d.PLACES[0]['name'])}</h2><p id="place-text">{e(d.PLACES[0]['text'])}</p><p id="place-guest"></p></article></div></section></div>'''

def treatment():
    link=f'<a class="button" href="{e(d.CONFIG["MASA_URL"])}">들어가기 ↗</a>' if d.CONFIG['MASA_URL'] else '<span class="closed-sign">준비 중</span>'
    return f'''<section class="treatment-room"><div class="treatment-backdrop"><img data-scene src="images/B/T.webp" alt="시술실"></div><div class="curtain left"></div><div class="curtain right"></div><div class="treatment-copy"><span class="eyebrow">04 / BEYOND THE CURTAIN</span><h1>커튼 안쪽.</h1><p>시술실 두 칸, 얇은 칸막이</p><button class="button" id="draw-curtain" aria-expanded="false">커튼 걷어 보기 <span>↗</span></button><div class="curtain-destination" hidden>{link}</div></div></section>'''

def write_page(filename,page,body,char=None):
    root=Path(__file__).resolve().parents[1]
    prefix='../' if '/' in filename else ''
    label=char['name'] if char else dict((r[0],r[1]) for r in d.ROOMS).get(page,'입구')
    nav=''.join(f'<a href="{prefix}{slug}.html" {"aria-current=\"page\"" if page==slug or page=="chart" and slug=="characters" else ""}><small>0{i}</small><span>{name}</span></a>' for i,(slug,name,_,_) in enumerate(d.ROOMS,1))
    tiles=''.join(f'<a class="directory-room" href="{prefix}{slug}.html"><img src="{prefix}images/B/{bg}.webp" alt="" loading="lazy"><span><small>0{i} / {en}</small><strong>{name}</strong></span><i>↗</i></a>' for i,(slug,name,en,bg) in enumerate(d.ROOMS,1))
    period=''.join(f'<button data-time="{t["id"]}" aria-pressed="false">{t["name"]}</button>' for t in d.TIMES)
    payload=dict(config=d.CONFIG,characters=d.CHARACTERS,rumors=d.RUMORS,voices=d.VOICES,places=d.PLACES,times=d.TIMES,expressions=d.EXPRESSIONS,copy=d.COPY,knots=d.KNOT_MAP,page=page,character=char['slug'] if char else None,prefix=prefix)
    for ch in payload['characters']:
        ch['availablePortrait']=(root/ch['portrait']).is_file()
        ch['gallery']=[[ch['portrait']] if ch['availablePortrait'] else []] + [[f"{d.CONFIG['CHARACTER_DIR']}/{ch['code']}_{n}.webp" for n in range(g['start'],g['end']+1) if (root/f"{d.CONFIG['CHARACTER_DIR']}/{ch['code']}_{n}.webp").is_file()] for g in d.EXPRESSION_GROUPS[1:]]
    payload=json.dumps(payload,ensure_ascii=False).replace('</','<\\/')
    guard='' if page=='index' else f'<script src="{prefix}assets/guard.js"></script>'
    preload={'index':'assets/art/alley.webp','home':'assets/art/reception.webp','rules':'assets/art/perfumery.webp','characters':d.CHARACTERS[0]['portrait']}.get(page,char['portrait'] if char else '')
    preload=f'<link rel="preload" as="image" href="{prefix}{preload}">' if preload else ''
    html=f'''<!doctype html><html lang="ko" data-time="evening"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101a17"><meta name="description" content="베일하운 골목 시술소. 방을 둘러보고, 다섯 인물의 이야기를 만나 보세요."><title>{e(label)} | 골목 시술소</title>{guard}<link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="{prefix}assets/fonts/Pretendard.woff2" as="font" type="font/woff2" crossorigin>{preload}<link rel="stylesheet" href="{prefix}assets/site.css?v=2"><script id="site-data" type="application/json">{payload}</script><script defer src="{prefix}assets/site.js?v=2"></script></head><body class="page-{page}"><a class="skip-link" href="#main">본문으로 건너뛰기</a><header class="topbar"><a class="brand" href="{prefix}{'index' if page=='index' else 'home'}.html"><svg viewBox="0 0 44 54" aria-hidden="true"><path d="M22 2 41 13v28L22 52 3 41V13Z M22 10v32M11 17l11 16 11-16M11 37l11-9 11 9"/></svg><span>골목 시술소<small>VEILHAUN</small></span></a><span class="header-location">THE BACK ALLEY <i></i> {e(label)}</span><div class="utilities"><div class="time-toggle" aria-label="시간대">{period}</div><button id="sound" class="utility" aria-label="효과음" aria-pressed="false"><span class="sound-bars" aria-hidden="true"><i></i><i></i><i></i><i></i></span></button><button id="menu-open" class="utility menu-icon" aria-label="방 안내"><span></span><span></span></button></div></header><main id="main" tabindex="-1">{body}</main><canvas id="atmosphere" aria-hidden="true"></canvas><nav class="room-tabs" aria-label="방">{nav}</nav><aside class="bell-widget"><div id="rumor-note" class="bell-note" hidden><span class="eyebrow">골목 소문</span><p id="rumor-text" aria-live="polite"></p><button id="rumor-close" class="note-close" aria-label="소문 쪽지 닫기">×</button></div><button id="bell" class="bell-button" aria-expanded="false" aria-label="접수 벨"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M8 27h24M11 26c0-14 18-14 18 0M19 10h2v5M6 31h28"/></svg><span>소문 듣기</span></button></aside><dialog id="room-menu"><form method="dialog"><button class="dialog-close" aria-label="닫기">×</button></form><span class="eyebrow">THE HOUSE DIRECTORY</span><h2>어디로 가시겠어요?</h2><nav class="directory-grid">{tiles}</nav><a class="exit-link" href="{prefix}index.html" data-exit>입구로 나가기 ↗</a><p class="key-hint">{e(d.COPY['keyboard_help'])}</p></dialog><dialog id="art-lightbox" aria-label="그림 크게 보기"><form method="dialog"><button class="dialog-close" aria-label="닫기">×</button></form><img alt=""><p>ESC를 눌러 돌아가기</p></dialog><div class="transition-veil" aria-hidden="true"></div></body></html>'''
    dest=root/filename
    dest.parent.mkdir(exist_ok=True)
    dest.write_text(html,encoding='utf-8')
